using Microsoft.AspNetCore.Mvc;using SlowCoffee.Application.DTOs;using SlowCoffee.Application.Interfaces;
namespace SlowCoffee.Api.Controllers;[ApiController][Route("api/produtos")]public class ProdutosController(IProdutoService s):ControllerBase{[HttpGet]public async Task<ActionResult> Get()=>Ok(await s.ListarAsync());[HttpGet("{id:int}")]public async Task<ActionResult> Get(int id)=>await s.ObterAsync(id) is { } x?Ok(x):NotFound();[HttpPost]public async Task<ActionResult> Post(ProdutoCreateDto d){var x=await s.CriarAsync(d);return CreatedAtAction(nameof(Get),new{id=x.Id},x);}[HttpPut("{id:int}")]public async Task<ActionResult> Put(int id,ProdutoCreateDto d)=>await s.AtualizarAsync(id,d)?NoContent():NotFound();[HttpDelete("{id:int}")]public async Task<ActionResult> Delete(int id)=>await s.ExcluirAsync(id)?NoContent():NotFound();}
